// LEARN(ts.everyday-types.unions-enums): enums emit objects, accept any number, and reject plain strings.

enum Level {
  Debug,
  Info,
  Warn,
}

// A numeric enum is an object with a reverse mapping, so it has twice the keys.
console.log(Object.keys(Level).join(","));
console.log(`${Level.Info} ${Level[1]}`);

// Literals are checked (TS 5.0+), but any number value is accepted:
// const bad: Level = 7;
// error TS2322: Type '7' is not assignable to type 'Level'.
const fromDb: number = 7;
const level: Level = fromDb; // compiles
console.log(`${level} -> ${Level[level]}`);

// String enums have no reverse mapping, and they are nominal: the plain
// string "active" is not a Status, even though that is its runtime value.
enum Status {
  Active = "active",
  Suspended = "suspended",
}
function label(s: Status): string {
  return s === Status.Active ? "Aktif" : "Askıda";
}
// label("active");
// error TS2345: Argument of type '"active"' is not assignable to parameter of type 'Status'.
const fromApi: string = "active";
console.log(label(Status.Active), label(fromApi as Status));
console.log(JSON.stringify(Status));

files.examples/02_as_const.ts:
// LEARN(ts.everyday-types.unions-enums): a const array or object plus a derived union replaces an enum, erasably.

// The values exist at run time; the type is derived from them, so they can't drift.
const LEVELS = ["debug", "info", "warn"] as const;
type Level = (typeof LEVELS)[number]; // "debug" | "info" | "warn"

// LEVELS.includes(s) with s: string fails: includes expects a Level.
// error TS2345: Argument of type 'string' is not assignable to parameter of type '"debug" | "info" | "warn"'.
function isLevel(s: string): s is Level {
  return (LEVELS as readonly string[]).includes(s);
}

// Identifiers are ASCII: lowercase them WITHOUT the Turkish locale.
const param = "INFO";
for (const key of [param.toLowerCase(), param.toLocaleLowerCase("tr")]) {
  console.log(isLevel(key) ? `level ${key}` : `unknown level ${key}`);
}

// When you also want named members, use an object with as const.
const Status = {
  Active: "active",
  Suspended: "suspended",
} as const;
type Status = (typeof Status)[keyof typeof Status]; // "active" | "suspended"

function label(s: Status): string {
  return s === Status.Active ? "Aktif" : "Askıda";
}
// Plain strings and named members are interchangeable: no cast needed.
console.log(label("active"), label(Status.Suspended));
console.log(Object.values(Status).join(","));

files.examples/03_type_vs_interface.ts:
// LEARN(ts.everyday-types.unions-enums): interfaces for object shapes, type aliases for unions and the rest.

interface BaseEvent {
  at: string;
}
interface Login extends BaseEvent {
  kind: "login";
  user: string;
}
interface Logout extends BaseEvent {
  kind: "logout";
  user: string;
  reason: "timeout" | "manual";
}
// A union (like a tuple or a primitive alias) can only be named with `type`.
type AuditEvent = Login | Logout;

// Declaration merging: a second `interface Login` adds a member to the first.
interface Login {
  ip?: string;
}

function describe(e: AuditEvent): string {
  if (e.kind === "login") {
    return `${e.at} ${e.user} giriş yaptı (${e.ip ?? "?"})`;
  }
  return `${e.at} ${e.user} çıktı: ${e.reason}`;
}

// extends reports a conflicting member at the declaration...
// interface Broken extends BaseEvent { at: number }
// error TS2430: Interface 'Broken' incorrectly extends interface 'BaseEvent'.
// ...while & silently makes it string & number, which is never:
type Odd = BaseEvent & { at: number };
// const odd: Odd = { at: "09:00" };
// error TS2322: Type 'string' is not assignable to type 'never'.

const events: AuditEvent[] = [
  { kind: "login", user: "ayşe", at: "09:00", ip: "10.0.0.7" },
  { kind: "logout", user: "ayşe", at: "17:30", reason: "manual" },
];
for (const e of events) console.log(describe(e));
